mapper.select:
SELECT f.id, left(f.session_id::text, 8) AS session_key, f.message_id, f.reason, f.detail::text AS detail, f.reviewed, f.reviewed_by, f.reviewed_at, f.review_comment, f.review_comment_ciphertext, f.review_comment_key_id, f.review_comment_encryption_version, f.created_at, s.scenario_id, sc.title AS scenario_title, s.current_node_id FROM chat_failure f JOIN chat_session s ON s.id = f.session_id JOIN scenario sc ON sc.id = s.scenario_id
f.reviewed = #{reviewed}
ORDER BY f.reviewed ASC, f.created_at DESC, f.id DESC LIMIT #{limit}

mapper.insert:
INSERT INTO chat_failure (
    session_id, message_id, reason, detail, reviewed, reviewed_by, reviewed_at,
    review_comment, review_comment_ciphertext, review_comment_key_id,
    review_comment_encryption_version
)
VALUES (
    #{sessionId}::uuid, #{messageId}, #{reason}, CAST(#{detail} AS jsonb),
    #{reviewed}, #{reviewedBy}, #{reviewedAt}, #{reviewComment},
    #{reviewCommentCiphertext}, #{reviewCommentKeyId}, #{reviewCommentEncryptionVersion}
)

mapper.update:
UPDATE chat_failure
SET review_comment = #{reviewComment},
    review_comment_ciphertext = #{reviewCommentCiphertext},
    review_comment_key_id = #{reviewCommentKeyId},
    review_comment_encryption_version = #{reviewCommentEncryptionVersion}
WHERE id = #{id}
